#include <zephyr/settings/settings.h> 
#include <zephyr/settings/settings_config.h> 

#include <zephyr/sys/util.h>
#include <zephyr/string.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(settings_config, CONFIG_SETTINGS_LOG_LEVEL);

extern const struct settings_config_var config_vars[];
extern const size_t config_vars_size;

static int settings_config_get(const struct settings_handler *ch, const char *name,
			       char *val, int val_len_max);
static int settings_config_set(const struct settings_handler *ch, const char *name,
			       size_t len, settings_read_cb read_cb, void *cb_arg);
static int settings_config_commit(const struct settings_handler *ch);
static int settings_config_export(const struct settings_handler *ch,
				  settings_export_cb cb, void *cb_arg);

static const struct settings_handler_static settings_config_handler = {
	.name = "config",
	.h_get = settings_config_get,
	.h_set = settings_config_set,
	.h_commit = settings_config_commit,
	.h_export = settings_config_export,
};

static int find_var_cmp(const void *key, const void *element)
{
	const char *key_str = key;
	const struct settings_config_var *element_var = element;

	return strcmp(key_str, element_var->name);
}

static const struct settings_config_var *find_var(const char *name)
{
	return bsearch(name, config_vars, config_vars_size,
		       sizeof(struct settings_config_var), find_var_cmp);
}

static int settings_config_get(const struct settings_handler *ch, const char *name,
			       char *val, int val_len_max)
{
	const struct settings_config_var *var;

	var = find_var(name);
	if (var == NULL) {
		return -ENOENT;
	}

	switch (var->type) {
#if UINTPTR_MAX < UINT64_MAX
	case SETTINGS_TYPE_U64:
	case SETTINGS_TYPE_I64:
		if (val_len_max < var->len) {
			return -EINVAL;
		}

		memcpy(val, (void *)var->val, var->len);
		return var->len;
#endif
	case SETTINGS_TYPE_BOOL:
	case SETTINGS_TYPE_U8:
	case SETTINGS_TYPE_I8:
	case SETTINGS_TYPE_U16:
	case SETTINGS_TYPE_I16:
	case SETTINGS_TYPE_U32:
	case SETTINGS_TYPE_I32:
#if UINTPTR_MAX >= UINT64_MAX
	case SETTINGS_TYPE_U64:
	case SETTINGS_TYPE_I64:
#endif
		if (val_len_max < var->len) {
			return -EINVAL;
		}

		memcpy(val, &var->val, var->len);
		return var->len;

	case SETTINGS_TYPE_STRING:
	case SETTINGS_TYPE_BYTES:
		if (val_len_max < var->len) {
			return -EINVAL;
		}

		memcpy(val, (void *)var->val, var->len);
		return var->len;

	default:
		return -EINVAL;
	}
}

static int settings_config_set(const struct settings_handler *ch, const char *name,
			       size_t len, settings_read_cb read_cb, void *cb_arg)
{
	ARG_UNUSED(ch);
	ARG_UNUSED(name);
	ARG_UNUSED(len);
	ARG_UNUSED(read_cb);
	ARG_UNUSED(cb_arg);

	return -ENOSYS;
}

static int settings_config_commit(const struct settings_handler *ch)
{
	ARG_UNUSED(ch);

	return 0;
}

static int settings_config_export(const struct settings_handler *ch,
				  settings_export_cb cb, void *cb_arg)
{
	int err;

	for (size_t i = 0; i < config_vars_size; i++) {
		const struct settings_config_var *var = &config_vars[i];
		char name_buf[SETTINGS_MAX_NAME_LEN + 1];
		int name_len;

		name_len = settings_name_next(var->name, NULL);
		if (name_len < 0 || name_len >= sizeof(name_buf)) {
			continue;
		}

		memcpy(name_buf, var->name, name_len);
		name_buf[name_len] = '\0';

		err = cb(name_buf, (void *)var->val, var->len, cb_arg);
		if (err) {
			return err;
		}
	}

	return 0;
}

int settings_config_init(void)
{
	return settings_register(&settings_config_handler);
}
